{
  "title": "Khoảng cách từ đỉnh Q của hình thoi MNPQ đến đường thẳng MP",
  "memory_declarations": [
    {
      "name": "M",
      "type": "point3",
      "initial_value": [1, 0, 2],
      "source_fact_id": "m_coords"
    },
    {
      "name": "N",
      "type": "point3",
      "initial_value": [4, 0, 2],
      "source_fact_id": "n_coords"
    },
    {
      "name": "P",
      "type": "point3",
      "initial_value": [5, 2, 4],
      "source_fact_id": "p_coords"
    },
    {
      "name": "Q",
      "type": "point3",
      "source_fact_id": "mnpq_rhombus"
    },
    {
      "name": "MP",
      "type": "line3"
    },
    {
      "name": "dist_q_mp",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "M",
      "at": [1, 0, 2],
      "source_fact_id": "m_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "N",
      "at": [4, 0, 2],
      "source_fact_id": "n_coords"
    },
    {
      "kind": "declare_point",
      "target_var": "P",
      "at": [5, 2, 4],
      "source_fact_id": "p_coords"
    },
    {
      "kind": "assign",
      "target_var": "vec_np",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "N",
        "to_point": "P"
      }
    },
    {
      "kind": "construct_point",
      "target_var": "Q",
      "expr": {
        "kind": "translate",
        "point": "M",
        "vector": "vec_np"
      },
      "label": "Đỉnh Q của hình thoi MNPQ",
      "pedagogical_intent": "Trong hình thoi MNPQ, vector MQ = vector NP."
    },
    {
      "kind": "construct_line",
      "target_var": "MP",
      "through_a": "M",
      "through_b": "P",
      "label": "Đường thẳng MP"
    },
    {
      "kind": "construct_point",
      "target_var": "H",
      "expr": {
        "kind": "project_onto",
        "point": "Q",
        "target": "MP"
      },
      "label": "Hình chiếu H của Q lên đường thẳng MP"
    },
    {
      "kind": "assign",
      "target_var": "dist_q_mp",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "Q",
        "wrt": "H"
      }
    }
  ]
}

