    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "source_fact_id": "coord_A"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [4, 0, 0],
      "source_fact_id": "coord_B"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 4, 0],
      "source_fact_id": "coord_C"
    },
    {
      "kind": "declare_point",
      "target_var": "A_prime",
      "at": [1, 1, 3],
      "source_fact_id": "coord_A_prime"
    },
    {
      "kind": "assign",
      "target_var": "vector_AA_prime",
      "expr": {
        "kind": "vector_from_points",
        "from_point": "A",
        "to_point": "A_prime"
      },
      "description": "Xác định vectơ AA' làm vectơ tịnh tiến cho các cạnh bên."
    },
    {
      "kind": "construct_point",
      "target_var": "B_prime",
      "expr": {
        "kind": "translate",
        "point": "B",
        "vector": "vector_AA_prime"
      },
      "description": "Dựng điểm B' bằng cách tịnh tiến điểm B theo vectơ AA', do ABC.A'B'C' là lăng trụ."
    },
    {
      "kind": "construct_point",
      "target_var": "C_prime",
      "expr": {
        "kind": "translate",
        "point": "C",
        "vector": "vector_AA_prime"
      },
      "description": "Dựng điểm C' bằng cách tịnh tiến điểm C theo vectơ AA', do ABC.A'B'C' là lăng trụ."
    },
    {
      "kind": "construct_point",
      "target_var": "I",
      "expr": {
        "kind": "midpoint",
        "a": "B_prime",
        "b": "C_prime"
      },
      "source_fact_id": "I_midpoint_B_prime_C_prime",
      "description": "Dựng điểm I là trung điểm của đoạn thẳng B'C'."
    },
    {
      "kind": "construct_line",
      "target_var": "B_prime_I",
      "through_a": "B_prime",
      "through_b": "I",
      "description": "Dựng đường thẳng B'I."
    },
    {
      "kind": "assign",
      "target_var": "khoang_cach_A_B_prime_I",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "A",
        "wrt": "B_prime_I"
      },
      "description": "Tính khoảng cách từ điểm A đến đường thẳng B'I."
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách sử dụng phép tịnh tiến để xác định các đỉnh của lăng trụ khi biết một cạnh bên và đáy, sau đó tính khoảng cách từ một điểm đến một đường thẳng."
}

{
  "title": "Tính khoảng cách từ điểm B đến mặt phẳng (AEF)",
  "memory_declarations": [
    {
      "name": "AEF",
      "type": "plane3"
    },
    {
      "name": "khoang_cach_b_aef",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [0, 0, 6],
      "model_assumption": "Điểm S được cho với tọa độ cụ thể."
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Điểm A được cho với tọa độ cụ thể."
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [6, 0, 0],
      "model_assumption": "Điểm B được cho với tọa độ cụ thể."
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 6, 0],
      "model_assumption": "Điểm D được cho với tọa độ cụ thể."
    },
    {
      "kind": "construct_point",
      "target_var": "E",
      "expr": {
        "kind": "midpoint",
        "a": "S",
        "b": "B"
      },
      "source_fact_id": "e_trung_diem_sb",
      "label": "Trung điểm E của SB"
    },
    {
      "kind": "construct_point",
      "target_var": "F",
      "expr": {
        "kind": "divide_segment",
        "a": "S",
        "b": "D",
        "ratio": {
          "kind": "literal",
          "value": 2
        }
      },
      "source_fact_id": "sf_2fd",
      "label": "Điểm F trên SD thỏa SF = 2FD"
    },
    {
      "kind": "construct_plane",
      "target_var": "AEF",
      "through": ["A", "E", "F"],
      "label": "Mặt phẳng (AEF)"
    },
    {
      "kind": "assign",
      "target_var": "khoang_cach_b_aef",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "B",
        "wrt": "AEF"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách dựng các điểm đặc biệt (trung điểm, chia đoạn theo tỉ lệ) và mặt phẳng, sau đó tính khoảng cách từ một điểm đến mặt phẳng trong không gian Oxyz."
}

